using Microsoft.AspNetCore.Http.HttpResults;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<ITodoStore, InMemoryTodoStore>();
var app = builder.Build();

app.MapGet("/todos", (ITodoStore store) => TypedResults.Ok(store.All()));

app.MapPost("/todos", (CreateTodo dto, ITodoStore store) =>
{
    if (string.IsNullOrWhiteSpace(dto.Title))
        return Results.ValidationProblem(new Dictionary<string, string[]>
        {
            ["Title"] = ["Title is required."]
        });

    var todo = store.Add(dto.Title);
    return TypedResults.Created($"/todos/{todo.Id}", todo);
});

app.MapDelete("/todos/{id:int}", (int id, ITodoStore store) =>
    store.Remove(id) ? TypedResults.NoContent() : TypedResults.NotFound());

app.Run();

// Types
public record CreateTodo(string Title);
public record Todo(int Id, string Title);

public interface ITodoStore
{
    IEnumerable<Todo> All();
    Todo Add(string title);
    bool Remove(int id);
}

public class InMemoryTodoStore : ITodoStore
{
    private readonly List<Todo> _items = [];
    private int _next = 1;
    public IEnumerable<Todo> All() => _items;
    public Todo Add(string title) { var t = new Todo(_next++, title); _items.Add(t); return t; }
    public bool Remove(int id) => _items.RemoveAll(t => t.Id == id) > 0;
}
