    const d2 = dx * dx + dy * dy;
    if (d2 < 10000) { p.vx += dx / 500; p.vy += dy / 500; }   // repel from pointer
    p.x += p.vx; p.y += p.vy;
    if (p.x < 0 || p.x > w) p.vx *= -1;
    if (p.y < 0 || p.y > h) p.vy *= -1;
    ctx.fillStyle = "#6cf";
    ctx.fillRect(p.x, p.y, 2, 2);
  }
  requestAnimationFrame(frame);
}

window.addEventListener("resize", () => { resize(); spawn(150); });
resize(); spawn(150); frame();
</script>
```

Scaling by `devicePixelRatio` keeps the canvas sharp on high-DPI screens. The animation loop uses `requestAnimationFrame`, which pauses automatically in background tabs.

