```python
import functools
import logging
import random
import time
from contextlib import contextmanager

log = logging.getLogger(__name__)

def retry(times=5, base=0.5, exceptions=(Exception,)):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            for attempt in range(1, times + 1):
                try:
                    return fn(*args, **kwargs)
                except exceptions as e:
                    if attempt == times:
                        raise
                    delay = base * 2 ** (attempt - 1) + random.uniform(0, base)  # jitter
                    log.warning("attempt %d failed (%s); retrying in %.2fs", attempt, e, delay)
                    time.sleep(delay)
        return wrapper
    return deco

@contextmanager
def timed(label):
    start = time.perf_counter()
    try:
        yield
    finally:
        print(f"{label}: {time.perf_counter() - start:.3f}s")

@retry(times=3, exceptions=(ConnectionError,))
def flaky():
    if random.random() < 0.7:
        raise ConnectionError("temporary failure")
    return "ok"

with timed("call"):
    print(flaky())
```

The `finally` in `timed` runs even if the body raises. Jitter spreads retries out so many clients don't hammer a recovering server at the same instant.

`Protocol` lets you define interfaces that any class with the right methods satisfies, with no inheritance needed.

```python
from typing import Protocol, runtime_checkable
from dataclasses import dataclass

class Storage(Protocol):
    def save(self, key: str, data: bytes) -> None: ...
    def load(self, key: str) -> bytes: ...

class MemoryStorage:                 # does NOT inherit from Storage
    def __init__(self) -> None:
        self._d: dict[str, bytes] = {}
    def save(self, key: str, data: bytes) -> None:
        self._d[key] = data
    def load(self, key: str) -> bytes:
        return self._d[key]

@dataclass
class Cache:
    backend: Storage                 # type checkers accept MemoryStorage here

    def put(self, name: str, payload: bytes) -> None:
        self.backend.save(name, payload)

cache = Cache(MemoryStorage())
cache.put("a", b"hello")
```

Run `mypy` to verify that the classes match the protocol. Add `@runtime_checkable` if you need `isinstance()` checks at runtime.

```rust
use std::fmt;
use std::fs;
use std::num::ParseIntError;

#[derive(Debug)]
enum ConfigError {
    Io(std::io::Error),
    Parse(ParseIntError),
    Missing(&'static str),
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            ConfigError::Io(e) => write!(f, "I/O error: {e}"),
            ConfigError::Parse(e) => write!(f, "invalid number: {e}"),
            ConfigError::Missing(k) => write!(f, "missing key: {k}"),
        }
    }
}

impl std::error::Error for ConfigError {}

// `From` impls let `?` convert the underlying errors automatically
impl From<std::io::Error> for ConfigError {
    fn from(e: std::io::Error) -> Self { ConfigError::Io(e) }
}
impl From<ParseIntError> for ConfigError {
    fn from(e: ParseIntError) -> Self { ConfigError::Parse(e) }
}

fn read_port(path: &str) -> Result<u16, ConfigError> {
    let text = fs::read_to_string(path)?;          // io::Error -> ConfigError
    let line = text
        .lines()
        .find(|l| l.starts_with("port="))
        .ok_or(ConfigError::Missing("port"))?;
    let port: u16 = line["port=".len()..].trim().parse()?; // ParseIntError -> ConfigError
    Ok(port)
}

fn main() {
    match read_port("app.conf") {
        Ok(p) => println!("port = {p}"),
        Err(e) => eprintln!("error: {e}"),
    }
}
```

Libraries often use `thiserror` to generate the `Display` and `From` boilerplate, and applications use `anyhow` for convenient error propagation.

Rayon turns sequential iterators into parallel ones with a single method change. Add `rayon = "1"` to `Cargo.toml`.

```rust
use rayon::prelude::*;

#[derive(Debug)]
struct Record { id: u32, score: f64 }

fn main() {
    let records: Vec<Record> = (0..1_000_000)
        .map(|i| Record { id: i, score: (i % 97) as f64 })
        .collect();

    // Sequential:  records.iter().filter(...).map(...).sum()
    // Parallel:    just swap iter() for par_iter()
    let total: f64 = records
        .par_iter()
        .filter(|r| r.score > 50.0)
        .map(|r| r.score * 1.1)
        .sum();

    let max_id = records
        .par_iter()
        .max_by(|a, b| a.score.partial_cmp(&b.score).unwrap())
        .map(|r| r.id);

    println!("total = {total:.2}, max id = {:?}", max_id);
}
```

Rayon uses a work-stealing thread pool. Parallelism only pays off when the per-item work is significant. For tiny closures, the sequential version is often faster.

```go
package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

type Job struct{ ID int }
type Result struct {
	JobID int
	Value int
}

func worker(ctx context.Context, id int, jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
	defer wg.Done()
	for {
		select {
		case <-ctx.Done():
			return
		case j, ok := <-jobs:
			if !ok {
				return
			}
			time.Sleep(100 * time.Millisecond)            // simulated work
			select {
			case results <- Result{JobID: j.ID, Value: j.ID * j.ID}:
			case <-ctx.Done():
				return
			}
		}
	}
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	jobs := make(chan Job)
	results := make(chan Result)
	var wg sync.WaitGroup

	for i := 1; i <= 4; i++ {
		wg.Add(1)
		go worker(ctx, i, jobs, results, &wg)
	}

	go func() {                       // producer
		defer close(jobs)
		for i := 1; i <= 20; i++ {
			select {
			case jobs <- Job{ID: i}:
			case <-ctx.Done():
				return
			}
		}
	}()

	go func() {                       // close results after all workers finish
		wg.Wait()
		close(results)
	}()

	for r := range results {
		fmt.Printf("job %d -> %d\n", r.JobID, r.Value)
	}
	if ctx.Err() != nil {
		fmt.Println("stopped:", ctx.Err())
	}
}
```

Every blocking send and receive also watches `ctx.Done()`, so the whole pipeline shuts down cleanly on timeout. Whoever closes a channel should be the sole sender.

```typescript
class TrieNode {
  children = new Map<string, TrieNode>();
  isWord = false;
}

class Trie {
  private root = new TrieNode();

  insert(word: string): void {
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) node.children.set(ch, new TrieNode());
      node = node.children.get(ch)!;
    }
    node.isWord = true;
  }

  private findNode(prefix: string): TrieNode | undefined {
    let node: TrieNode | undefined = this.root;
    for (const ch of prefix) {
      node = node.children.get(ch);
      if (!node) return undefined;
    }
    return node;
  }

  autocomplete(prefix: string, limit = 10): string[] {
    const start = this.findNode(prefix);
    const results: string[] = [];
    const dfs = (node: TrieNode, path: string) => {
      if (results.length >= limit) return;
      if (node.isWord) results.push(path);
      for (const [ch, child] of node.children) dfs(child, path + ch);
    };
    if (start) dfs(start, prefix);
    return results;
  }
}

const t = new Trie();
["car", "card", "care", "cat", "dog"].forEach(w => t.insert(w));
console.log(t.autocomplete("car"));   // ["car", "card", "care"]
```

Lookup costs O(length of prefix), independent of how many words are stored. For huge vocabularies, replace the `Map`s with compressed (radix) nodes to save memory.

```cpp
#include <iostream>
#include <limits>
#include <queue>
#include <utility>
#include <vector>

using Graph = std::vector<std::vector<std::pair<int, int>>>;  // node -> (neighbor, weight)

std::vector<long long> dijkstra(const Graph& g, int src, std::vector<int>* parent = nullptr) {
    const long long INF = std::numeric_limits<long long>::max();
    std::vector<long long> dist(g.size(), INF);
    if (parent) parent->assign(g.size(), -1);

    using State = std::pair<long long, int>;                        // (distance, node)
    std::priority_queue<State, std::vector<State>, std::greater<>> pq;

    dist[src] = 0;
    pq.emplace(0, src);
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d > dist[u]) continue;                                  // stale entry
        for (auto [v, w] : g[u]) {
            if (d + w < dist[v]) {
                dist[v] = d + w;
                if (parent) (*parent)[v] = u;
                pq.emplace(dist[v], v);
            }
        }
    }
    return dist;
}

int main() {
    Graph g(4);
    g[0] = {{1, 1}, {2, 4}};
    g[1] = {{2, 2}, {3, 5}};
    g[2] = {{3, 1}};
    std::vector<int> parent;
    auto dist = dijkstra(g, 0, &parent);
    for (int i = 0; i < 4; ++i) std::cout << i << ": " << dist[i] << '\n';
}
```

`std::greater<>` turns the max-heap into a min-heap. The `stale entry` check skips outdated queue items instead of supporting decrease-key. Complexity is O((V+E) log V).

